"""Copy the Tukua icon into the native Android project (android/ is generated by `expo prebuild` and is
not in git; once it exists, icon and splash changes in app.json no longer reach it until the next
prebuild). Run after `node scripts/generate-tukua-icon.cjs`:

    python scripts/apply-android-icon.py
"""
import os
import re
from PIL import Image, ImageDraw

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
ICONS = os.path.join(ROOT, 'assets', 'images', 'icons')
LOGO = os.path.join(ROOT, 'assets', 'images', 'logo')
RES = os.path.join(ROOT, 'android', 'app', 'src', 'main', 'res')

ICON_BACKGROUND = '#172C1F'
SPLASH_BACKGROUND = '#FFFFFF'

DENSITIES = {'mdpi': 1, 'hdpi': 1.5, 'xhdpi': 2, 'xxhdpi': 3, 'xxxhdpi': 4}

square = Image.open(os.path.join(ICONS, 'tukua-app-icon-1024.png')).convert('RGBA')
foreground = Image.open(os.path.join(ICONS, 'tukua-adaptive-foreground-1024.png')).convert('RGBA')
notification = Image.open(os.path.join(ICONS, 'tukua-notification-96.png')).convert('RGBA')
tile = Image.open(os.path.join(LOGO, 'splash-tukua-hd.png')).convert('RGBA')


def sized(img, px):
    return img.resize((px, px), Image.LANCZOS)


def rounded(img, radius_ratio):
    px = img.size[0]
    mask = Image.new('L', img.size, 0)
    ImageDraw.Draw(mask).rounded_rectangle((0, 0, px - 1, px - 1), int(px * radius_ratio), fill=255)
    out = img.copy()
    out.putalpha(mask)
    return out


def splash_logo(px):
    # Android 12+ shows the splash icon inside a circle two thirds of this canvas, so the tile sits at
    # half the canvas with transparent room around it.
    canvas = Image.new('RGBA', (px, px), (0, 0, 0, 0))
    inner = sized(tile, px // 2)
    canvas.alpha_composite(inner, ((px - inner.size[0]) // 2, (px - inner.size[1]) // 2))
    return canvas


for name, k in DENSITIES.items():
    mip = os.path.join(RES, f'mipmap-{name}')
    drw = os.path.join(RES, f'drawable-{name}')
    legacy = round(48 * k)
    rounded(sized(square, legacy), 0.22).save(os.path.join(mip, 'ic_launcher.webp'), 'WEBP', quality=95)
    round_icon = sized(square, legacy)
    mask = Image.new('L', round_icon.size, 0)
    ImageDraw.Draw(mask).ellipse((0, 0, legacy - 1, legacy - 1), fill=255)
    round_icon.putalpha(mask)
    round_icon.save(os.path.join(mip, 'ic_launcher_round.webp'), 'WEBP', quality=95)
    sized(foreground, round(108 * k)).save(os.path.join(mip, 'ic_launcher_foreground.webp'), 'WEBP', quality=95)
    sized(notification, round(24 * k)).save(os.path.join(drw, 'notification_icon.png'))
    splash_logo(round(288 * k)).save(os.path.join(drw, 'splashscreen_logo.png'))
    print(name, 'done')

colors = os.path.join(RES, 'values', 'colors.xml')
with open(colors, encoding='utf-8') as f:
    xml = f.read()
xml = re.sub(r'(<color name="iconBackground">)[^<]*', rf'\g<1>{ICON_BACKGROUND}', xml)
xml = re.sub(r'(<color name="splashscreen_background">)[^<]*', rf'\g<1>{SPLASH_BACKGROUND}', xml)
with open(colors, 'w', encoding='utf-8') as f:
    f.write(xml)
print('colors.xml: iconBackground', ICON_BACKGROUND, 'splashscreen_background', SPLASH_BACKGROUND)
